head.b:skin:
:root {
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --text-color: #e2e8f0;
    --text-muted: #94a3b8;
    --accent-color: #38bdf8;
    --border-color: #334155;
}
body {
    background-color: var(--bg-color);
    color: var(--text-color);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    margin: 0; padding: 0; line-height: 1.6;
}
header {
    background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
    border-bottom: 1px solid var(--border-color);
    padding: 40px 20px; text-align: center;
}
header h1 { margin: 0; font-size: 2.5rem; color: #ffffff; }
header p { color: var(--text-muted); margin-top: 10px; font-size: 1.1rem; }

.nav-container {
    background: #111827;
    border-bottom: 1px solid var(--border-color);
    padding: 12px 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 30px;
    flex-wrap: wrap;
}
.nav-container a {
    color: var(--text-muted) !important;
    text-decoration: none !important;
    font-weight: 500;
    font-size: 0.95rem;
    transition: color 0.2s;
}
.nav-container a:hover {
    color: var(--accent-color) !important;
}

.container { max-width: 850px; margin: 40px auto; padding: 0 20px; }
.post-card, .post-body {
    background-color: var(--card-bg); border: 1px solid var(--border-color);
    border-radius: 12px; padding: 30px; box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3); margin-bottom: 30px;
}
h2, h3 { color: #ffffff; }
a { color: var(--accent-color); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; height: auto; border-radius: 8px; }
footer { text-align: center; padding: 40px; color: var(--text-muted); border-top: 1px solid var(--border-color); font-size: 0.9rem; }

/* --- ANÚNCIOS INVISÍVEIS / RETRÁTEIS --- */
.ad-slot-topo, .ad-slot-artigo {
    display: none !important; height: 0 !important; width: 0 !important;
    margin: 0 !important; padding: 0 !important; overflow: hidden !important; visibility: hidden !important; opacity: 0 !important;
}
